// v0.100.1 — PDC-10 (hotfix regression net): rows must NOT pass a Dataview
// Link object as the click target. `target: (p) => p.file.link` forwarded a
// Link object into app.workspace.openLinkText(), whose getLinkpath calls
// .indexOf on a string → "TypeError: e.indexOf is not a function" on every
// row click (latent since v0.50.0; surfaced when v0.100.0 made rows the
// primary navigation). BeaconCards' default targetFn (p.file.path, a string)
// is the correct path — the helper must not override it with file.link.
async function casePDC10NoLinkObjectTarget() {
  console.log("\n--- Case PDC-10: ProjectDocsCards passes no Link-object click target ---");
  const src = fs.readFileSync(
    path.join(WORKSHOP, "platform/blueprints/project/helpers/project-docs-cards.js"),
    "utf8"
  );
  assertTrue("PDC-10: no file.link reference (Link object) in the helper",
    !/file\.link/.test(src));
}

// v0.100.2 — DHB-1 (Docs Hub template button fix): originally the standalone
// entity-create:doc-note block on Docs Hub.md had to use the canonical
// `customJS.EntityCreate.render(dv, {instance})` dispatch (NOT the broken
// AccentButton guard form which passed `dv` instead of `dv.container`).
//
// v0.102.0 S4 update: the standalone block was REMOVED — ProjectDocsSections
// now renders per-section + New buttons internally via the same canonical
// EntityCreate.render dispatch (verified in HC-V01020-PDS-4). DHB-1 now
// guards that (a) ProjectDocsSections is wired on the Docs Hub template,
// AND (b) the broken AccentButton-with-doc-note-args form is absent (in case
// a future edit reintroduces a standalone block, it must NOT use the broken
// form).
//
// v0.103.0 S3 update: ProjectDocsSections is RETIRED from the Docs Hub
// template — ProjectDocsIndex (the new sections-index landing helper) takes
// over. DHB-1 now guards (a) ProjectDocsIndex is wired on the Docs Hub
// template, AND (b) the broken AccentButton form is still absent.
async function caseDHB1DocsHubTemplateCanonical() {
  console.log("\n--- Case DHB-1: Docs Hub template wires ProjectDocsIndex + no broken AccentButton form ---");
  const src = fs.readFileSync(
    path.join(WORKSHOP, "platform/blueprints/project/templates/Docs Hub.md"),
    "utf8"
  );
  assertTrue("DHB-1: ProjectDocsIndex invoked via customjs-guard view (v0.103.0 S3 contract)",
    /customjs-guard["'\s,\n]+[^}]*class\s*:\s*["']ProjectDocsIndex["']/.test(src)
      || /customJS\.ProjectDocsIndex\.render/.test(src));
  assertTrue("DHB-1: broken AccentButton-with-doc-note-args form absent",
    !/class:\s*"AccentButton",\s*args:\s*\[\{\s*id:\s*"doc-note"/.test(src));
}

