async function caseV0990SchemaA5() {
  console.log(`\n--- Case HC-V0990-SCHEMA-A5: schema 4 input is idempotent — NO re-reset ---`);
  try {
    const { normalizeLearnedWeightsV4 } = require("../blueprints/cowork/helpers/ingest-feedback-helper.js");
    const raw = { schema_version: 4, engagements: { headspace: {
      per_kind: { chat: { weight: 1.05, ticks: 9, skips: 4, warmup: false, per_person: {}, per_channel: {}, per_topic: {} } },
      totals: { engaged_days: ["2026-06-13"], satisfaction: [{ day: "2026-06-13", useful: true }], scanned_days: [], feedback_ingested_days: [], warmup_until: null },
    } } };
    const out = normalizeLearnedWeightsV4(raw);
    const c = out.engagements.headspace.per_kind.chat;
    const rawStr = JSON.parse(JSON.stringify(raw));
    rawStr.schema_version = "4";
    const outStr = normalizeLearnedWeightsV4(rawStr);
    const strKept = outStr.engagements.headspace.per_kind.chat.skips === 4
      && outStr.engagements.headspace.per_kind.chat.warmup === false;
    const aliasInput = JSON.parse(JSON.stringify(raw));
    const aliasOut = normalizeLearnedWeightsV4(aliasInput);
    aliasOut.engagements.headspace.totals.scanned_days.push("MUTATED");
    const noAlias = !aliasInput.engagements.headspace.totals.scanned_days.includes("MUTATED");
    assertTrue(
      "HC-V0990-SCHEMA-A5: already-4 input (int OR string) passes through — skips/warmup/satisfaction kept; output totals do not alias input",
      c.skips === 4 && c.warmup === false && out.engagements.headspace.totals.satisfaction.length === 1 && strKept && noAlias
    );
  } catch (e) { assertTrue("HC-V0990-SCHEMA-A5: 4 idempotent", false, e && e.message); }
}

async function caseV0990SchemaA6() {
  console.log(`\n--- Case HC-V0990-SCHEMA-A6: appendSatisfaction — boolean-only, same-day overwrite, 30-day window trim (v0.101.0 per-cadence semantics) ---`);
  try {
    const { appendSatisfaction } = require("../blueprints/cowork/helpers/ingest-feedback-helper.js");
    let totals = { satisfaction: [] };
    for (let i = 0; i < 32; i++) {
      // 2026-05-01 .. 2026-06-01 — 32 consecutive days; final append's 30-day
      // window (cutoff 2026-05-02, inclusive) drops only the first day.
      const day = new Date(Date.UTC(2026, 4, 1 + i)).toISOString().slice(0, 10);
      totals = appendSatisfaction(totals, day, i % 2 === 0);
    }
    const trimmed = totals.satisfaction.length === 31 && totals.satisfaction[0].day === "2026-05-02";
    const overwritten = appendSatisfaction({ satisfaction: [{ day: "2026-06-13", useful: false }] }, "2026-06-13", true);
    const ambiguousNoop = appendSatisfaction({ satisfaction: [] }, "2026-06-13", "ambiguous");
    assertTrue(
      "HC-V0990-SCHEMA-A6: 30-day window trims by day (oldest dropped); same-(day, cadence) re-log overwrites (legacy entry defaults eod-review); non-boolean is a no-op",
      trimmed && overwritten.satisfaction.length === 1 && overwritten.satisfaction[0].useful === true
        && ambiguousNoop.satisfaction.length === 0
    );
  } catch (e) { assertTrue("HC-V0990-SCHEMA-A6: appendSatisfaction", false, e && e.message); }
}

